'use strict';
const $=id=>document.getElementById(id),M=Model,S=SimpleDemo,P=ProcessDemo;
let state=P.initial(),playing=false,timer=null,compact=false;
const names={segment:'Segmentation & access',mfa:'Secure communications',rbac:'Least privilege',edr:'Endpoint protection',backup:'Isolated backups',edge:'Edge protection & resilience',training:'Training & response'};
const f=n=>n.toFixed(1),countLabel=(n,word)=>n+' '+word+(n===1?'':'s');
function stop(){clearTimeout(timer);timer=null;playing=false;}
function draw(){const h=P.frame(state);$('scene').innerHTML=P.svg(state,compact,playing);$('sceneTitle').textContent=state.view==='hotel'?'Trace the incident through the hotel':'The same incident, mapped to the network';$('sceneMode').textContent=state.mode==='original'?'Original environment':'Improved plan';$('hotelView').classList.toggle('active',state.view==='hotel');$('networkView').classList.toggle('active',state.view==='network');$('hotelView').setAttribute('aria-pressed',state.view==='hotel');$('networkView').setAttribute('aria-pressed',state.view==='network');$('follow').checked=state.follow;
 $('impact').textContent=state.step<0?'Ready to simulate':`${countLabel(h.affected.length,'area')} · ${countLabel(h.departments.length,'department')}`;
 $('impactDetail').textContent=state.step<0?'Affected areas appear as the scenario progresses.':h.affected.map(P.label).join(', ')||'No production area is affected at this stage.';
 $('defense').textContent=state.step<2?'Not checked yet':h.hp.active&&!h.sessionRevoked?'Monitoring the decoy':h.guarded?'Path contained':'Path remains exposed';$('defenseDetail').textContent=state.step<2?'The next checkpoint shows whether the selected control applies.':h.controlName+': '+(h.sessionRevoked?'The suspicious session is revoked and denied production access.':h.hp.active?'The decoy is being monitored; session revocation has not happened yet.':h.guarded?h.blockReason:'The current plan does not contain this path.');
 $('recovery').textContent=state.step<5?'Recovery not started':h.pendingDisclosure?'Disclosure cannot be undone':h.recovered.length?`${countLabel(h.recovered.length,'area')} recovered (simulated)`:h.recoveryActive?'Preparing recovery':h.affected.length?'Recovery control missing':'No production recovery needed';$('recoveryDetail').textContent=state.step<5?'The recovery source and direction appear after containment.':h.recoveryActive?'From '+P.label(h.recoveryFrom)+' to '+P.label(h.recoveryTo)+'.':h.pendingDisclosure?'Restoring a system cannot undo an earlier disclosure.':'Retain containment and review the incident record.';
}
function render(){const p=S.current(state),story=P.frame(state);$('modeBefore').classList.toggle('active',state.mode==='original');$('modeAfter').classList.toggle('active',state.mode==='improved');$('modeBefore').setAttribute('aria-pressed',state.mode==='original');$('modeAfter').setAttribute('aria-pressed',state.mode==='improved');$('scenario').value=state.scenario;$('play').textContent=playing?'Pause':state.step===P.COUNT-1?'Replay':state.step>=0?'Resume':'Play scenario';$('phaseTitle').textContent=story.title;$('phaseText').textContent=story.text;$('progress').textContent=state.step<0?'Not started':`${state.step+1} / ${P.COUNT} · ${playing?'Playing':state.step===P.COUNT-1?'Playback complete':'Paused'}`;
 $('steps').innerHTML=['Entry','Access','Check','Impact','Contain','Recover','Verify','Outcome'].map((v,i)=>`<span class="${i===state.step?'current':i<state.step?'done':''}">${i+1} ${v}</span>`).join('');
 $('caseStatus').textContent=story.incident;$('caseStatus').className='case-status '+(story.closed?'closed':story.finished?'open':'ongoing');$('entryLocation').textContent=P.label(story.origin);$('currentLocation').textContent=story.location;$('currentControl').textContent=story.controlActive?story.controlName:state.step<2?'Awaiting check':'Not effective on this path';
 $('journey').innerHTML=P.journey(state).map(n=>`<li class="${n.status}"><span>${n.index+1}</span><b>${n.name}</b><small>${{pending:'Not reached',visited:'Visited',current:'Current location',blocked:'Blocked here',isolated:'Session isolated',triggered:'Decoy triggered'}[n.status]}</small></li>`).join('');
 $('honeyToggle').checked=!!state.honey;$('honeyToggle').disabled=!story.hp.supported;$('honeyDescription').textContent=!story.hp.supported?'Honeypots are not treated as a universal defense for this scenario.':!state.honey?'Optional: assume this attempt reaches an isolated decoy, then show detection and containment.':!story.hp.ready?'Requires segmentation and least privilege in the improved plan.':story.sessionRevoked?'Decoy session isolated; only the suspicious session is revoked.':'An isolated decoy is configured. Targeting and containment are assumptions, excluded from the risk score.';
 draw();renderBudget();renderControls();renderMatrix();
 $('status').textContent=state.mode==='original'?'Viewing the original environment. Switch plans to compare the same stage.':!M.evaluate(state.improved).feasible?'The improved plan is over budget. Adjust the controls or apply a recommendation below.':'Hotel and network views share one timeline. Switching views preserves progress.';$('singleStep').disabled=state.step===P.COUNT-1;
}
function schedule(){if(!playing)return;if(state.step===P.COUNT-1){stop();render();return;}timer=setTimeout(()=>{state.step++;render();schedule();},P.frame(state).duration);}
function start(){if(playing){stop();render();return;}if(state.step<0||state.step===P.COUNT-1)state.step=0;playing=true;render();schedule();}
function recommendation(){const q=M.clone(state.improved);q.selected=M.solve(q).ids;return q;}
function renderBudget(){const candidate=recommendation(),v=M.evaluate(candidate),current=M.evaluate(state.improved);$('budget').value=state.improved.budget;$('budgetValue').textContent=state.improved.budget+' units';$('recommendation').textContent=candidate.selected.map(id=>names[id]).join(', ')||'No additional controls fit this budget';$('riskChange').textContent=`${f(v.baseline)} → ${f(v.risk)}`;$('suggestCost').textContent=`Recommended cost ${f(v.cost)} / ${state.improved.budget}`;$('budgetState').textContent=current.feasible?`Current plan cost: ${f(current.cost)}; within budget.`:`Current plan exceeds budget by ${f(current.cost-state.improved.budget)} units.`;$('budgetState').classList.toggle('warning',!current.feasible);$('riskNote').textContent='Illustrative index for the recommended set. Apply the recommendation to update the simulation.';}
function renderControls(){
 const suggested=recommendation().selected;
 $('controlList').innerHTML=M.controls.map(c=>{const chosen=state.improved.selected.includes(c.id),recommended=suggested.includes(c.id);return '<label class="control '+(chosen?'chosen':'')+'"><input type="checkbox" data-control="'+c.id+'" '+(chosen?'checked':'')+'><span>'+names[c.id]+'<small>'+c.name+'</small><em>'+(chosen?'Configured':'Not configured')+(recommended?' · Recommended':'')+'</em></span><b>'+c.cost+' u</b></label>';}).join('');
 document.querySelectorAll('[data-control]').forEach(c=>c.onchange=()=>{stop();const id=c.dataset.control;state.improved.selected=c.checked?[...new Set([...state.improved.selected,id])]:state.improved.selected.filter(x=>x!==id);state.mode='improved';state.step=-1;render();$('status').textContent='Controls updated. The scenario has returned to the start.';});
}
function renderMatrix(){
 $('modernMatrix').innerHTML='<table><thead><tr><th>Editable demo policy</th>'+M.resources.map(r=>'<th>'+r+'</th>').join('')+'</tr></thead><tbody>'+M.roles.map((r,i)=>'<tr><th>'+r+'</th>'+state.improved.policy[i].map((v,j)=>'<td><select aria-label="'+r+' / '+M.resources[j]+'" data-policy="'+i+','+j+'">'+['—','R','RW'].map(x=>'<option '+(x===v?'selected':'')+'>'+x+'</option>').join('')+'</select></td>').join('')+'</tr>').join('')+'</tbody></table>';
 document.querySelectorAll('[data-policy]').forEach(e=>e.onchange=()=>{stop();const [i,j]=e.dataset.policy.split(',').map(Number);state.improved.policy[i][j]=e.value;state.improved.policyMode='custom';state.mode='improved';state.step=-1;render();});
 $('matrixStatus').textContent=M.enabled(state.improved,'rbac')?'Least privilege is enabled. Data access is checked against the editable policy above.':'Least privilege is disabled. Editing this matrix alone will not block access.';
}
function init(){
 $('honeyToggle').onchange=e=>{stop();state.honey=e.target.checked;state.step=-1;render();};
 $('scenario').innerHTML=M.scenarios.map((s,i)=>`<option value="${i}">${s.name}</option>`).join('');$('scenario').onchange=e=>{stop();state.scenario=+e.target.value;state.step=-1;render();};
 $('modeBefore').onclick=()=>{stop();state=S.switchMode(state,'original');render();};$('modeAfter').onclick=()=>{stop();state=S.switchMode(state,'improved');render();};
 $('play').onclick=start;$('restart').onclick=()=>{stop();state.step=-1;render();};$('singleStep').onclick=()=>{stop();state.step=Math.min(P.COUNT-1,state.step+1);render();};
 $('hotelView').onclick=()=>{state.view='hotel';draw();};$('networkView').onclick=()=>{state.view='network';draw();};$('follow').onchange=e=>{state.follow=e.target.checked;draw();};
 $('budget').oninput=e=>{stop();state.improved.budget=+e.target.value;render();};$('applyBudget').onclick=()=>{stop();state={...state,improved:recommendation(),mode:'improved',step:-1};render();$('status').textContent='Recommendation applied within budget. The scenario has returned to the start.';};
 const matrix=M.matrix; $('originalMatrix').innerHTML='<table><thead><tr><th>Original matrix</th>'+M.resources.map(r=>'<th>'+r+'</th>').join('')+'</tr></thead><tbody>'+M.roles.map((r,i)=>'<tr><th>'+r+'</th>'+matrix[i].map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
 $('effectTable').innerHTML='<table><thead><tr><th>Illustrative control</th><th>Cost</th>'+M.scenarios.map(s=>'<th>'+s.name+'</th>').join('')+'</tr></thead><tbody>'+M.controls.map(c=>'<tr><th>'+names[c.id]+'</th><td>'+c.cost+'</td>'+c.e.map(n=>'<td>'+Math.round(n*100)+'%</td>').join('')+'</tr>').join('')+'</tbody></table>';
 const resize=()=>{const next=$('scene').getBoundingClientRect().width<600;if(next!==compact){compact=next;draw();}};compact=$('scene').getBoundingClientRect().width<600;render();if('ResizeObserver'in window)new ResizeObserver(resize).observe($('scene'));window.addEventListener('pagehide',stop);window.addEventListener('pageshow',()=>{if(!playing)render();});
}
init();
